mapper.update:
UPDATE strategy_application
SET after_expected_asset = #{afterExpectedAsset}
WHERE application_id = #{applicationId}
  AND user_id = #{userId}

mapper.select:
SELECT 
FROM strategy_application
WHERE application_id = #{applicationId}
  AND user_id = #{userId}

SELECT 
FROM strategy_application
WHERE analysis_id = #{analysisId}
  AND user_id = #{userId}
LIMIT 1

SELECT 
FROM strategy_application
WHERE user_id = #{userId}
  AND guidance_id = #{guidanceId}
  AND applied_guidance_action = #{action}
  AND applied_investment_frequency = #{frequency}
  AND applied_recurring_contribution_amount = #{contributionAmount}
LIMIT 1

SELECT 
FROM strategy_application
WHERE user_id = #{userId}
ORDER BY applied_at DESC, application_id DESC
LIMIT #{limit} OFFSET #{offset}
